136: function pointToMap(clientX, clientY) {
137:   const r = canvas.getBoundingClientRect();
138:   const px = clientX - r.left;
139:   const py = clientY - r.top;
140:   return {
141:     px, py,
142:     nx: px / Math.max(1, r.width),
143:     ny: py / Math.max(1, r.height),
144:     inside: px >= 0 && py >= 0 && px <= r.width && py <= r.height,
145:   };
146: }
