148: let toastTimer = 0;
149: function toast(message, type = '') {
150:   const wrap = $('#toasts');
151:   const key = message + type;
152:   const now = performance.now();
153:   const existing = [...wrap.children].find(el => el.dataset.key === key);
154:   if (existing && now - toastTimer < 500) return;
155:   toastTimer = now;
156:   const el = document.createElement('div');
157:   el.className = `toast ${type}`;
158:   el.dataset.key = key;
159:   el.textContent = message;
160:   wrap.appendChild(el);
161:   while (wrap.children.length > 3) wrap.removeChild(wrap.firstChild);
162:   setTimeout(() => {
163:     el.classList.add('out');
164:     setTimeout(() => el.remove(), 320);
165:   }, 2600);
166: }
