209: function onCardDown(e, type, card) {
210:   if (e.button !== undefined && e.button !== 0) return;
211:   if (!game.started) return;
212:   if (game.phase === 'victory' || game.phase === 'defeat') return;
213:   e.preventDefault();
214:   audio.ensure();
215:   const def = TOWERS[type];
