217:     audio.error();
218:     toast(`Need ${def.cost - game.credits} more credits for ${def.short}`, 'bad');
219:     return;
220:   }
221:   drag = {
222:     type,
223:     card,
224:     startX: e.clientX,
225:     startY: e.clientY,
226:     moved: false,
227:     pointerId: e.pointerId,
228:     captured: false,
229:   };
230:   try {
231:     card.setPointerCapture(e.pointerId);
232:     drag.captured = true;
233:   } catch {}
234: }
