236: window.addEventListener('pointermove', (e) => {
237:   if (!drag) return;
238:   if (!drag.moved) {
239:     const dx = e.clientX - drag.startX;
240:     const dy = e.clientY - drag.startY;
241:     if (Math.hypot(dx, dy) < 7) return;
242:     drag.moved = true;
