253:       <span class="ghost-name">${TOWERS[drag.type].short}</span>
254:       <span class="ghost-cost">${COIN}${TOWERS[drag.type].cost}</span>`;
255:     dragGhost.classList.remove('hidden');
256:     dragGhost.classList.remove('bad');
257:     ghostVisible = true;
258:     audio.ui();
259:   }
260:   if (!drag.moved) return;
261:   dragGhost.style.left = `${e.clientX}px`;
262:   dragGhost.style.top = `${e.clientY}px`;
263:   const pos = pointToMap(e.clientX, e.clientY);
