415:   $('#statRange').textContent = Math.round(lv.range);
416:   $('#statRate').textContent = `${(1 / lv.cooldown).toFixed(1)}/s`;
417:   const mode = TARGET_MODES.find(m => m.id === t.mode) || TARGET_MODES[0];
418:   $('#targetMode').textContent = mode.label;
419:   $('#targetBtn').title = `Priority: ${mode.desc}. Tap to change.`;
