483: function syncIntel(h) {
484:   const key = `${game.started}:${h.wave}:${h.phase}`;
485:   if (key === lastIntelKey) return;
486:   lastIntelKey = key;
487:   const body = $('#intelBody');
488:   const threat = $('#intelThreat');
489:   const title = $('#intelTitle');
490:   if (!body) return;
491:   if (!game.started) {
492:     body.innerHTML = '<span class="intel-tip">Deploy the outpost to see droid movements.</span>';
493:     threat.textContent = 'STANDBY';
494:     threat.className = 'threat';
495:     return;
496:   }
497:   if (h.phase === 'victory' || h.phase === 'defeat') {
498:     body.innerHTML = '<span class="intel-tip">Mission concluded. Redeploy for another run.</span>';
499:     threat.textContent = h.phase === 'victory' ? 'SECURED' : 'OFFLINE';
500:     threat.className = 'threat';
501:     return;
502:   }
503:   title.textContent = h.phase === 'wave' ? 'WAVE INTEL' : 'NEXT WAVE INTEL';
504:   const specs = makeWave(h.wave);
505:   const counts = {};
506:   for (const s of specs) counts[s.type] = (counts[s.type] || 0) + 1;
507:   const order = ['droid', 'scout', 'tank', 'boss'];
508:   const labels = { droid: 'B1', scout: 'STAP', tank: 'B2', boss: 'CMD' };
509:   body.innerHTML = order
510:     .filter(t => counts[t])
511:     .map(t => `<span class="intel-chip"><i class="enemy-dot ${t === 'boss' ? 'boss' : ''}" style="--dotc:${ENEMY_TYPES[t].color}"></i><b>${counts[t]}</b>${labels[t]}</span>`)
512:     .join('');
513:   let level = 'LOW';
514:   if (h.wave > 18 || h.wave % 10 === 0) level = 'EXTREME';
515:   else if (h.wave > 11) level = 'HIGH';
516:   else if (h.wave > 4) level = 'MODERATE';
517:   threat.textContent = `${level} THREAT`;
518:   threat.className = `threat ${level === 'MODERATE' ? 'moderate' : level === 'HIGH' ? 'high' : level === 'EXTREME' ? 'extreme' : ''}`;
519: }
