521: function syncUI(force = false) {
522:   if (!game) return;
523:   const h = game.hud();
524: 
525:   const creditsEl = $('#credits');
526:   const livesEl = $('#lives');
527:   if (force || h.credits !== lastHud.credits) {
528:     creditsEl.textContent = fmt(h.credits);
529:     lastHud.credits = h.credits;
530:   }
531:   if (force || h.lives !== lastHud.lives) {
532:     livesEl.textContent = h.lives;
533:     livesEl.parentElement.classList.toggle('low', h.lives <= 5);
534:     if (h.lives < lastHud.lives && game.started) {
535:       livesEl.parentElement.classList.remove('bump');
536:       void livesEl.parentElement.offsetWidth;
537:       livesEl.parentElement.classList.add('bump');
538:     }
539:     lastHud.lives = h.lives;
540:   }
541: 
542:   const waveEl = $('#waveTag');
543:   const cap = h.endless ? '&infin;' : TOTAL_WAVES;
544:   waveEl.innerHTML = `WAVE ${h.wave} <i>/ ${cap}</i>`;
545:   $('#waveSub').textContent = h.phase === 'wave' ? `${h.alive + h.queue} hostile${h.alive + h.queue === 1 ? '' : 's'}` : h.phase === 'build' ? (h.wave > 1 ? 'Build phase' : 'Prepare defenses') : h.phase === 'victory' ? 'Relay held' : 'Relay lost';
546:   $('#waveProgress').style.width = `${(h.phase === 'wave' ? h.progress : 0) * 100}%`;
547: 
548:   const statusEl = $('#waveStatus');
