24: function samplePath(points, w, h, per = 18) {
25:   const src = points.map(p => [p[0] * w, p[1] * h]);
26:   const out = [];
27:   for (let i = 0; i < src.length - 1; i++) {
28:     const p0 = src[Math.max(0, i - 1)];
29:     const p1 = src[i];
30:     const p2 = src[i + 1];
31:     const p3 = src[Math.min(src.length - 1, i + 2)];
32:     for (let s = 0; s < per; s++) {
33:       const t = s / per;
34:       const t2 = t * t;
35:       const t3 = t2 * t;
36:       const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
37:       const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
38:       out.push([x, y]);
39:     }
40:   }
41:   out.push(src[src.length - 1].slice());
42:   return out;
43: }
