45: function pointDistanceToPath(x, y, pts) {
46:   let best = Infinity;
47:   for (let i = 0; i < pts.length - 1; i++) {
48:     const ax = pts[i][0], ay = pts[i][1];
49:     const bx = pts[i + 1][0], by = pts[i + 1][1];
50:     const dx = bx - ax, dy = by - ay;
51:     const l2 = dx * dx + dy * dy || 1;
52:     let t = ((x - ax) * dx + (y - ay) * dy) / l2;
53:     t = clamp(t, 0, 1);
54:     const px = ax + dx * t, py = ay + dy * t;
55:     const d = (x - px) ** 2 + (y - py) ** 2;
56:     if (d < best) best = d;
57:   }
58:   return Math.sqrt(best);
59: }
