325: function distanceToPath(x, y, pts) {
326:   let best = Infinity;
327:   for (let i = 0; i < pts.length - 1; i++) {
328:     const ax = pts[i][0], ay = pts[i][1], bx = pts[i + 1][0], by = pts[i + 1][1];
329:     const dx = bx - ax, dy = by - ay;
330:     const l2 = dx * dx + dy * dy || 1;
331:     let t = ((x - ax) * dx + (y - ay) * dy) / l2;
332:     t = clamp(t, 0, 1);
333:     const px = ax + dx * t, py = ay + dy * t;
334:     best = Math.min(best, Math.hypot(x - px, y - py));
335:   }
336:   return best;
337: }
