+  ctx.beginPath();
+  ctx.moveTo(8.6, -1.6);
+  ctx.lineTo(11, -3);
+  ctx.moveTo(8.6, 1.6);
+  ctx.lineTo(11, 3);
+  ctx.stroke();
+}
+
+/* —— Sith enforcer —— */
+function drawSithBody(ctx, e, time, def) {
+  const walk = Math.sin(time * 6 + (e.phase || 0)) * 0.8;
