+  ctx.fill();
+  ctx.strokeStyle = 'rgba(120, 40, 44, 0.4)';
+  ctx.lineWidth = 0.8;
+  ctx.stroke();
+
+  // legs
+  ctx.strokeStyle = '#120d10';
+  ctx.lineWidth = 2.4;
+  ctx.lineCap = 'round';
+  ctx.beginPath();
+  ctx.moveTo(-2, -3);
+  ctx.lineTo(-5 + walk, -9);
+  ctx.moveTo(-2, 3);
+  ctx.lineTo(-5 - walk, 9);
+  ctx.stroke();
+
+  // robe body
+  const body = ctx.createLinearGradient(0, -8, 0, 8);
+  body.addColorStop(0, '#2c2026');
+  body.addColorStop(1, '#100b0e');
