407:     const i1 = Math.min(n - 1, i0 + 1);
408:     const frac = f - i0;
409:     const a = this.pathPts[i0];
410:     const b = this.pathPts[i1];
411:     e.x = a[0] + (b[0] - a[0]) * frac;
412:     e.y = a[1] + (b[1] - a[1]) * frac;
413:     e.angle = Math.atan2(b[1] - a[1], b[0] - a[0]);
414:   }
415: 
416:   completeWave() {
417:     if (!this.waveActive) return;
418:     this.waveActive = false;
419:     this.spawnQueue = null;
420:     const bonus = waveReward(this.waveNumber);
421:     this.credits += bonus;
422:     this.creditsEarned += bonus;
423:     this.audio.waveClear();
424:     this.callbacks.toast?.(`Wave ${this.waveNumber} cleared  +${bonus} credits`, 'good');
425:     this.effects.push({ kind: 'ring', x: this.map.base.x * this.w, y: this.map.base.y * this.h, r: 12 * this.S, maxR: 90 * this.S, color: '#8ff0b0', width: 2, life: 0.8, max: 0.8 });
426: 
427:     if (!this.endless && this.waveNumber >= this.map.waves) {
428:       this.win();
429:       return;
430:     }
431:     this.waveNumber++;
432:     this.phase = 'build';
433:     this.selected = null;
434:     this.callbacks.onWaveClear?.(this.waveNumber, bonus);
