464:   /* ---------------- update ---------------- */
465: 
466:   update(rawDt) {
467:     const rdt = Math.min(rawDt, 0.15);
468:     this.realTime += rdt;
469:     if (!this.started || this.paused || this.phase === 'victory' || this.phase === 'defeat') {
470:       this.updateFx(rdt);
471:       return;
472:     }
473:     // Fixed substeps keep the simulation real-time even at low frame rates.
474:     const total = rdt * this.speed;
475:     const steps = Math.max(1, Math.ceil(total / 0.033));
476:     const dt = total / steps;
477:     for (let i = 0; i < steps; i++) {
478:       this.stepSim(dt);
479:       if (this.phase === 'victory' || this.phase === 'defeat') break;
480:     }
481:   }
482: 
483:   stepSim(dt) {
484:     this.time += dt;
485: 
486:     // ambient weather
487:     this.dustTimer -= dt;
488:     if (this.dustTimer <= 0) {
489:       const amb = this.theme.ambient || { mode: 'dust', color: 'rgba(255, 233, 185, 0.35)', density: 1 };
490:       this.dustTimer = (0.35 + Math.random() * 0.5) / (amb.density || 1);
491:       if (this.particles.length < 300) {
492:         const w = this.w;
493:         const h = this.h;
494:         const S = this.S;
495:         let p;
496:         if (amb.mode === 'snow') {
497:           p = {
498:             x: Math.random() * w * 1.1,
499:             y: -10,
500:             vx: (6 + Math.random() * 18) * S,
501:             vy: (26 + Math.random() * 42) * S,
502:             life: 5 + Math.random() * 4,
503:             max: 9,
504:             size: (0.8 + Math.random() * 1.9) * S,
505:             color: amb.color,
506:             glow: Math.random() > 0.6,
507:             gravity: 0,
508:             drag: 0.998,
509:           };
510:         } else if (amb.mode === 'ember') {
511:           p = {
512:             x: Math.random() * w,
513:             y: h * (0.4 + Math.random() * 0.7),
514:             vx: (6 + Math.random() * 22) * S,
515:             vy: -(14 + Math.random() * 34) * S,
516:             life: 2 + Math.random() * 3,
517:             max: 5,
518:             size: (0.7 + Math.random() * 1.6) * S,
519:             color: amb.color,
520:             glow: true,
521:             gravity: -6,
522:             drag: 0.995,
523:           };
524:         } else if (amb.mode === 'mote') {
525:           p = {
526:             x: Math.random() * w,
527:             y: h * (0.3 + Math.random() * 0.7),
528:             vx: (4 + Math.random() * 14) * S,
529:             vy: -(2 + Math.random() * 12) * S,
530:             life: 3 + Math.random() * 3,
531:             max: 6,
532:             size: (0.7 + Math.random() * 1.3) * S,
533:             color: amb.color,
534:             glow: true,
535:             gravity: 0,
536:             drag: 0.997,
537:           };
538:         } else {
539:           p = {
540:             x: Math.random() * w,
541:             y: h * (0.25 + Math.random() * 0.7),
542:             vx: (10 + Math.random() * 26) * S,
543:             vy: (2 + Math.random() * 8) * S,
544:             life: 3.5 + Math.random() * 4,
545:             max: 7,
546:             size: (0.7 + Math.random() * 1.2) * S,
547:             color: amb.color,
548:             glow: false,
549:             gravity: 0,
550:             drag: 0.99,
551:           };
552:         }
553:         this.particles.push(p);
554:       }
555:     }
556: 
557:     if (this.waveActive && this.spawnQueue) {
558:       this.spawnTimer -= dt;
559:       let guard = 0;
560:       while (this.spawnTimer <= 0 && this.spawnQueue.length && guard++ < 20) {
561:         const spec = this.spawnQueue.shift();
562:         this.spawnEnemy(spec);
563:         this.spawnTimer += this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
564:       }
565:     }
566: 
567:     this.updateEnemies(dt);
568:     this.updateTowers(dt);
569:     this.updateProjectiles(dt);
570:     this.updateFx(dt);
571:     this.cleanup();
572: 
573:     if (this.waveActive && (!this.spawnQueue || this.spawnQueue.length === 0) && this.enemies.length === 0) {
574:       this.completeWave();
575:     }
576:     if (this.baseFlash > 0) this.baseFlash = Math.max(0, this.baseFlash - dt * 2);
577:     if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 34);
578:   }
579: 
580:   updateFx(dt) {
581:     for (const e of this.effects) e.life -= dt;
582:     for (const p of this.particles) {
583:       p.life -= dt;
584:       p.x += p.vx * dt;
585:       p.y += p.vy * dt;
586:       if (p.gravity) p.vy += p.gravity * dt;
587:       if (p.drag) { p.vx *= p.drag; p.vy *= p.drag; }
588:     }
589:     this.effects = this.effects.filter(e => e.life > 0);
590:     this.particles = this.particles.filter(p => p.life > 0 && p.x > -80 && p.x < this.w + 80 && p.y > -80 && p.y < this.h + 80);
591:   }
592: 
593:   updateEnemies(dt) {
594:     for (const e of this.enemies) {
595:       if (e.dead) continue;
596:       if (e.hitFlash > 0) e.hitFlash = Math.max(0, e.hitFlash - dt);
597:       if (e.slowT > 0) {
598:         e.slowT -= dt;
599:         if (e.slowT <= 0) { e.slowT = 0; e.slowFactor = 0; }
600:       }
601:       const slowMul = e.slowT > 0 ? 1 - e.slowFactor : 1;
602:       const pxPerSec = e.speed * this.S * slowMul;
603:       e.t += (pxPerSec * dt) / this.pathLen;
604:       if (e.t >= 1) {
605:         e.dead = true;
606:         this.leakEnemy(e);
607:       } else {
608:         this.positionEnemy(e);
609:       }
610:     }
611:   }
612: 
613:   leakEnemy(e) {
614:     this.lives -= e.leak;
615:     this.baseFlash = 1;
616:     this.shake = Math.max(this.shake, 8);
617:     this.audio.leak();
618:     this.effects.push({ kind: 'ring', x: this.map.base.x * this.w, y: this.map.base.y * this.h, r: 20 * this.S, maxR: 105 * this.S, color: '#ff6e58', width: 3, life: 0.7, max: 0.7 });
619:     this.effects.push({ kind: 'flash', x: this.map.base.x * this.w, y: this.map.base.y * this.h, r: 100 * this.S, color: 'rgba(255, 90, 70, 0.5)', life: 0.5, max: 0.5 });
620:     this.callbacks.toast?.(`Relay hit!  −${e.leak} integrity`, 'bad');
621:     this.callbacks.onLeak?.(e.leak);
622:     if (this.bossRef === e) this.bossRef = null;
623:     if (this.lives <= 0) {
624:       this.lives = 0;
625:       this.defeat();
626:     }
627:     if (this.phase === 'defeat') {
628:       // let the current frame finish; game over overlay takes over
629:     }
630:   }
