632:   updateTowers(dt) {
633:     for (const t of this.towers) {
634:       if (t.flash > 0) t.flash = Math.max(0, t.flash - dt * 3);
635:       t.cooldownLeft -= dt;
636:       t.recoil = Math.max(0, t.recoil - dt * 7);
637:       const target = this.pickTarget(t);
638:       if (target) {
639:         const desired = Math.atan2(target.y - t.y, target.x - t.x);
640:         t.targetAngle = desired;
641:         t.angle = angleLerp(t.angle, desired, dt * 16);
642:         if (t.cooldownLeft <= 0) {
643:           this.fire(t, target);
644:           t.cooldownLeft = t.cooldown;
645:         }
646:       } else {
647:         t.targetAngle = t.angle;
648:         t.angle += dt * 0.18;
649:       }
650:     }
651:   }
652: 
653:   pickTarget(t) {
654:     const R2 = (t.range * this.S) ** 2;
655:     let best = null;
656:     let bestScore = -Infinity;
657:     for (const e of this.enemies) {
658:       if (e.dead) continue;
659:       const d2 = (e.x - t.x) ** 2 + (e.y - t.y) ** 2;
660:       if (d2 > R2) continue;
661:       let score;
662:       if (t.mode === 'first') score = e.t;
663:       else if (t.mode === 'last') score = -e.t;
664:       else if (t.mode === 'strong') score = e.hp;
665:       else score = -d2;
666:       if (score > bestScore) { bestScore = score; best = e; }
667:     }
668:     return best;
669:   }
670: 
671:   muzzle(t, target) {
672:     const a = Math.atan2(target.y - t.y, target.x - t.x);
673:     const d = (t.type === 'bounty' ? 23 : 17) * this.S;
674:     return { x: t.x + Math.cos(a) * d, y: t.y + Math.sin(a) * d, angle: a };
675:   }
676: 
677:   fire(t, target) {
678:     const def = TOWERS[t.type];
679:     const muzzle = this.muzzle(t, target);
680:     t.recoil = 1;
681:     t.flash = 0.4;
682:     if (def.attack === 'bullet') {
683:       this.projectiles.push({
684:         kind: 'bullet', x: muzzle.x, y: muzzle.y, target,
685:         speed: def.projectileSpeed * this.S, damage: t.damage,
686:         towerType: t.type, life: 2.4, angle: muzzle.angle,
687:       });
688:       this.audio.shot('scout');
689:       this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 11 * this.S, color: 'rgba(255, 220, 130, 0.55)', life: 0.08, max: 0.08 });
690:       this.spark(muzzle.x, muzzle.y, 2, '#ffd77f', 1.6);
691:     } else if (def.attack === 'rocket') {
692:       this.projectiles.push({
693:         kind: 'rocket', x: muzzle.x, y: muzzle.y, target,
694:         speed: def.projectileSpeed * this.S, damage: t.damage,
695:         splash: t.splash * this.S, towerType: t.type, life: 3.4, angle: muzzle.angle, source: { x: t.x, y: t.y },
696:       });
697:       this.audio.shot('rocket');
698:       this.spark(muzzle.x, muzzle.y, 4, '#ffb066', 2.2);
699:     } else if (def.attack === 'ion') {
700:       this.projectiles.push({
701:         kind: 'ion', x: muzzle.x, y: muzzle.y, target,
702:         speed: def.projectileSpeed * this.S, damage: t.damage,
703:         slow: t.slow, slowDuration: t.slowDuration, splash: 36 * this.S,
704:         towerType: t.type, life: 3, angle: muzzle.angle, spin: 0,
705:         source: { x: t.x, y: t.y },
706:       });
707:       this.audio.shot('ion');
708:       this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 16 * this.S, color: 'rgba(130, 230, 255, 0.6)', life: 0.14, max: 0.14 });
709:     } else if (def.attack === 'laser') {
710:       const hits = [target];
711:       const extra = (t.chain || 1) - 1;
712:       if (extra > 0) {
713:         const near = this.enemies
714:           .filter(e => !e.dead && e !== target && Math.hypot(e.x - target.x, e.y - target.y) < 95 * this.S && Math.hypot(e.x - t.x, e.y - t.y) < t.range * this.S)
715:           .sort((a, b) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(b.x - target.x, b.y - target.y));
716:         for (let i = 0; i < extra && i < near.length; i++) hits.push(near[i]);
717:       }
718:       let fx = muzzle;
719:       for (const e of hits) {
720:         this.effects.push({ kind: 'beam', x1: fx.x, y1: fx.y, x2: e.x, y2: e.y, color: '#ff6252', width: 3.1 * this.S, life: 0.11, max: 0.11 });
721:         this.damageEnemy(e, t.damage, { tower: t });
722:         this.spark(e.x, e.y, 3, '#ffab7f', 2.4);
723:         fx = { x: e.x, y: e.y };
724:       }
725:       this.audio.shot('laser');
726:       this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 14 * this.S, color: 'rgba(255, 110, 90, 0.5)', life: 0.1, max: 0.1 });
727:     } else if (def.attack === 'sniper') {
728:       const bonus = ENEMY_TYPES[target.type].boss ? def.bossBonus : 1;
729:       const dmg = t.damage * bonus;
730:       this.effects.push({ kind: 'beam', x1: muzzle.x, y1: muzzle.y, x2: target.x, y2: target.y, color: '#ffce7c', width: 2.2 * this.S, life: 0.16, max: 0.16 });
731:       this.effects.push({ kind: 'flash', x: target.x, y: target.y, r: 22 * this.S, color: 'rgba(255, 220, 150, 0.55)', life: 0.18, max: 0.18 });
732:       this.damageEnemy(target, dmg, { tower: t });
733:       this.spark(target.x, target.y, 8, '#ffd98a', 2.8);
734:       this.audio.shot('sniper');
735:       this.shake = Math.max(this.shake, ENEMY_TYPES[target.type].boss ? 2.5 : 0.7);
736:     } else if (def.attack === 'aura') {
737:       const R2 = (t.range * this.S) ** 2;
738:       let hurt = 0;
739:       for (const e of this.enemies) {
740:         if (e.dead) continue;
741:         if ((e.x - t.x) ** 2 + (e.y - t.y) ** 2 < R2) {
742:           this.damageEnemy(e, t.damage, { tower: t });
743:           hurt++;
744:         }
745:       }
746:       const slashAngle = this.time * 3 + t.phase;
747:       this.effects.push({ kind: 'slash', x: t.x, y: t.y, r: t.range * this.S * 0.92, a0: slashAngle, a1: slashAngle + 1.9, color: '#8fd6ff', width: 3 * this.S, life: 0.16, max: 0.16 });
748:       if (hurt > 0) this.audio.shot('jedi');
749:     }
750:   }
