752:   damageEnemy(e, amount, opts = {}) {
753:     if (e.dead) return;
754:     const def = ENEMY_TYPES[e.type];
755:     let dmg = amount;
756:     if (!opts.trueDamage) dmg = Math.max(1, dmg - (def.armor || 0));
757:     e.hp -= dmg;
758:     e.hitFlash = 0.1;
759:     if (e.hp <= 0) this.killEnemy(e, opts.tower);
