795:     this.effects.push({ kind: 'flash', x, y, r: radius * 0.7, color: big ? 'rgba(255, 210, 140, 0.6)' : 'rgba(255, 170, 100, 0.45)', life: big ? 0.3 : 0.16, max: big ? 0.3 : 0.16 });
796:     const n = big ? 28 : 12;
797:     for (let i = 0; i < n; i++) {
