802:       this.particles.push({
803:         x, y,
804:         vx: Math.cos(a) * sp * this.S, vy: Math.sin(a) * sp * this.S,
805:         life, max: life, size,
806:         color: i % 3 === 0 ? '#ffe8b0' : i % 3 === 1 ? '#ff9a55' : '#8b4e2f',
807:         glow: i % 3 !== 2, gravity: big ? 40 : 30, drag: 0.975,
